import { defineComponent, onMounted, ref } from "vue";
//#region src/client/app/components/ClientOnly.ts
const ClientOnly = defineComponent({ setup(_, { slots }) {
	const show = ref(false);
	onMounted(() => {
		show.value = true;
	});
	return () => show.value && slots.default ? slots.default() : null;
} });
//#endregion
export { ClientOnly };
